  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Zalcitabine, a polar nucleoside with a primary amino group and low logP, shows approximately 70-90% absolute oral bioavailability in humans, demonstrating that low lipophilicity and polar functionality do not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Lamivudine, another polar primary-amine nucleoside, has an absolute oral bioavailability of 68.6 ± 11% under fasted conditions, directly supporting high F for a similarly polar, low-logP molecule in the fasted state.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Saccharin, a small imide/sulfonimide, shows 88 ± 2% fraction absorbed in fasted humans, indicating that imide-containing small molecules can be very well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Bromazepam, a fused benzodiazepinone with an amide/lactam-like core, has an absolute oral bioavailability of 86% in humans, supporting high F for fused lactam/benzazepinone scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Ondansetron, a fused heterocyclic amide, has an absolute oral bioavailability of about 85%, further supporting that fused amide/lactam-containing molecules can achieve high oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability well above the 20% threshold, mostly 50-100%, including polar primary-amine nucleosides, imide-containing small molecules, and fused lactams. The query's low logP and polar groups are therefore not disqualifying, and the weight of direct human bioavailability evidence supports a high prediction.",
  "evidence_gaps": [
    "No direct pharmacokinetic data exist for the exact query molecule.",
    "First-pass metabolism of the primary aromatic amine is not directly measured.",
    "Potential transporter-mediated efflux or imide instability is not experimentally characterized for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

